// ---------- couleurs ----------
function rgb(h){ h=h.replace('#',''); return { r:parseInt(h.slice(0,2),16)/255, g:parseInt(h.slice(2,4),16)/255, b:parseInt(h.slice(4,6),16)/255 }; }
function solid(h,a){ const p={ type:'SOLID', color:rgb(h) }; if(a!==undefined && a<1) p.opacity=a; return p; }
function grad(c1,c2,deg){
  const a=(deg===undefined?135:deg)*Math.PI/180, c=Math.cos(a), s=Math.sin(a);
  const mn=Math.min(0,c,s,c+s), range=Math.abs(c)+Math.abs(s);
  return { type:'GRADIENT_LINEAR',
    gradientTransform:[[c/range, s/range, -mn/range],[-s/range, c/range, 0.5-(c-s)*0.5/range]],
    gradientStops:[ {position:0,color:Object.assign(rgb(c1),{a:1})}, {position:1,color:Object.assign(rgb(c2),{a:1})} ] };
}
const toPaint=(f,a)=>(typeof f==='string')?solid(f,a):f;
const GREEN_GRAD=()=>grad(C.deep,C.forest,135);
const SIGNATURE=()=>grad(C.leaf,C.gold,0);          // progression : vert → jaune
const BRAND_GRAD=()=>grad(C.gold,C.forest,135);     // dégradé signature jaune → vert

// ---------- polices ----------
const F={};
async function tryLoad(family,styles){ for(const st of styles){ try{ await figma.loadFontAsync({family,style:st}); return {family,style:st}; }catch(e){} } return null; }
async function initFonts(){
  F.reg  = await tryLoad('DM Sans',['Regular'])||await tryLoad('Inter',['Regular']);
  F.med  = await tryLoad('DM Sans',['Medium'])||await tryLoad('Inter',['Medium'])||F.reg;
  F.bold = await tryLoad('DM Sans',['Bold'])||await tryLoad('Inter',['Bold'])||F.reg;
  F.head = await tryLoad('Fraunces',['Regular','Medium','SemiBold','Bold'])||F.bold;
}

