// ----- mode sombre : conversion automatique d'un écran clair (palette corrigée) -----
function hexOf(c){ const h=v=>Math.round(v*255).toString(16).padStart(2,'0'); return ('#'+h(c.r)+h(c.g)+h(c.b)).toUpperCase(); }
function darkPaint(p,node,stroke){
  if(!p) return p;
  if(p.type==='SOLID'){
    const hx=hexOf(p.color), isT=node.type==='TEXT'; let to=null;
    if(!stroke){
      if(hx==='#F5F8F5') to=C.darkBg;
      else if(hx==='#FFFFFF'&&!isT) to=C.darkSurface;
      else if(hx==='#00290B'&&isT) to=C.darkText;
      else if(hx==='#296740') to=isT?C.darkAccent:C.leaf;
      else if(hx==='#3D8652'&&isT) to=C.darkAccent;
    } else {
      if(hx==='#296740'||hx==='#3D8652') to=C.leaf;
      else if(hx==='#00290B') to=C.darkText;
    }
    if(!to) return p;
    const q=Object.assign({},p,{color:rgb(to)}); if(stroke&&q.opacity!==undefined&&q.opacity<0.25) q.opacity=0.28; return q;
  }
  if(p.type==='GRADIENT_LINEAR'){
    const map={'#00290B':'#0B2E17','#296740':'#1E5535'};
    return Object.assign({},p,{gradientStops:p.gradientStops.map(st=>{ const to=map[hexOf(st.color)]; return to?{position:st.position,color:Object.assign(rgb(to),{a:st.color.a})}:st; })});
  }
  return p;
}
function darkify(frame){
  const nodes=[frame].concat(frame.findAll(()=>true));
  nodes.forEach(n=>{ try{ if(Array.isArray(n.fills)) n.fills=n.fills.map(p=>darkPaint(p,n,false)); if(Array.isArray(n.strokes)&&n.strokes.length) n.strokes=n.strokes.map(p=>darkPaint(p,n,true)); }catch(e){} });
}
function darkScreen(base,fn,h){
  const start=LINKS.length; const f=screen(base+' (mode sombre)',C.mist,fn,h); darkify(f);
  for(let i=start;i<LINKS.length;i++){ const l=LINKS[i]; if(!l.dest) continue; const bare=l.dest.slice(0,l.dest.length-SUF.length);
    if(DARKSET.indexOf(bare)>=0) l.dest=bare+' (mode sombre)'+SUF; else if(bare===N.settings) l.dest=N.settingsDark+SUF; }
  return f;
}
