function mkSection(page,name,frames,x,y,cols){
  cols=cols||6; const gapX=60,gapY=100,padX=60,padTop=100;
  let sec=null; try{ sec=figma.createSection(); sec.name=name; page.appendChild(sec); }catch(e){ sec=null; }
  const nR=Math.ceil(frames.length/cols), rowH=[]; for(let r=0;r<nR;r++){ let m=0; for(let c=0;c<cols;c++){ const f=frames[r*cols+c]; if(f) m=Math.max(m,f.height); } rowH.push(m); }
  const rowY=r=>{ let t=padTop; for(let k=0;k<r;k++) t+=rowH[k]+gapY; return t; };
  const w=padX*2+Math.min(cols,frames.length)*(W+gapX)-gapX, h=rowY(nR-1)+rowH[nR-1]+60;
  if(sec){ sec.x=x; sec.y=y; sec.resizeWithoutConstraints(w,h); }
  frames.forEach((f,i)=>{ const fx=padX+(i%cols)*(W+gapX), fy=rowY(Math.floor(i/cols)); if(sec){ sec.appendChild(f); f.x=fx; f.y=fy; } else { page.appendChild(f); f.x=x+fx; f.y=y+fy; } });
  return h;
}
