async function finalizeLinks(){
  let ok=0,ko=0; const errs=[];
  for(const l of LINKS){
    try{
      const tr=l.sm?{type:'SMART_ANIMATE',easing:{type:'EASE_IN_AND_OUT'},duration:0.85}:{type:'DISSOLVE',easing:{type:'EASE_OUT'},duration:0.22}; let act;
      if(l.toast){ const t=FRAMES[l.toastKey]; if(!t){ MISSLINK.add(l.toastKey); continue; } act={type:'NODE',destinationId:t.id,navigation:'OVERLAY',transition:tr,preserveScrollPosition:false}; }
      else { const dest=FRAMES[l.dest]; if(!dest||!l.node){ MISSLINK.add(l.dest); continue; } act={type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:tr,preserveScrollPosition:false}; }
      const trig=l.trigger==='AFTER_TIMEOUT'?{type:'AFTER_TIMEOUT',timeout:l.delay}:{type:'ON_CLICK'};
      await l.node.setReactionsAsync([{trigger:trig,actions:[act]}]); ok++;
    }catch(e){ ko++; if(errs.length<2) errs.push(String(e&&e.message?e.message:e)); }
  }
  for(const k of Object.keys(FRAMES)){ if(k.indexOf('Toast · ')===0){ try{ await FRAMES[k].setReactionsAsync([{trigger:{type:'AFTER_TIMEOUT',timeout:1.8},actions:[{type:'CLOSE'}]}]); }catch(e){} } }
  return {ok,ko,errs};
}
